    item_id: item.id,
    entry_type: input2.entryType,
    qty_delta: qtyDelta,
    unit_id: item.base_unit_id,
    balance_after: Math.max(0, newBalance),
    occurred_at: input2.occurredAt,
    description: input2.description ?? null
