      where.push(
        "(i.name LIKE ? OR e.entry_no LIKE ? OR e.source_ref LIKE ? OR e.description LIKE ?)"
      );
      params.push(`%${search}%`, `%${search}%`, `%${search}%`, `%${search}%`);
